<?php
declare(strict_types=1);
use App\Core\Application;use App\Services\{TaskQueueService,WatchFolderService};
require dirname(__DIR__).'/vendor/autoload.php';$app=Application::boot(dirname(__DIR__));$db=$app->get(\PDO::class);$db->exec('INSERT IGNORE INTO bouquet_content_items(bouquet_id,content_item_id) SELECT bc.bouquet_id,c.id FROM bouquet_categories bc JOIN content_items c ON c.category_id=bc.category_id');$db->exec('INSERT IGNORE INTO package_content_items(package_id,content_item_id) SELECT pc.package_id,c.id FROM package_categories pc JOIN content_items c ON c.category_id=pc.category_id');$db->exec('INSERT IGNORE INTO package_content_items(package_id,content_item_id) SELECT pb.package_id,bi.content_item_id FROM package_bouquets pb JOIN bouquet_content_items bi ON bi.bouquet_id=pb.bouquet_id JOIN bouquets b ON b.id=pb.bouquet_id AND b.active=1');$queue=$app->get(TaskQueueService::class);$minute=date('YmdHi');$day=date('Ymd');$app->get(WatchFolderService::class)->dispatchDue();$queue->enqueue('sync_balancers',['heartbeat_ttl'=>90],10,'sync-balancers-'.$minute);$queue->enqueue('cleanup_sessions',[],20,'cleanup-sessions-'.$minute);if(date('H:i')==='03:00')$queue->enqueue('rotate_logs',[],200,'rotate-logs-'.$day);$queue->recoverPending();echo "Scheduler ejecutado\n";
